<script setup lang="ts">
import draggable from 'vuedraggable'
import { ArrowLeft, Plus, Copy, Trash2, GripVertical, Undo2, Redo2, Download, Clipboard, History, LayoutTemplate, Search, ChevronUp, ChevronDown, Settings2, Layers3, X, Save, Sparkles } from 'lucide-vue-next'
import { sanitizeHtml, htmlAssetIds, newBlockId, cloneSnapshot, prepareComponent, extractFieldValues, type ComponentData, type Block, type Article, type Resource } from '@qinbian/shared'
const props=withDefaults(defineProps<{id:string;target?:'document'|'resource'}>(),{target:'document'})
const ctx=useQinbian(),entity=ref<any>(),title=ref(''),themeSetId=ref('mine'),blocks=ref<Block[]>([]),selected=ref(''),resourcesList=ref<Resource[]>([]),resourceQuery=ref(''),selectedMedia=ref(0),width=ref(375),panel=ref<'properties'|'ai'>('properties'),leftOpen=ref(false),rightOpen=ref(false),activeEditor=shallowRef<any>(null),activeEditorBlock=ref(''),status=ref('正在打开…'),historyOpen=ref(false),versions=ref<any[]>([]),sourceOpen=ref(false),sourceCode=ref(''),manualCopy=ref(''),recover=ref<any>(null)
const revision=ref(1),loading=ref(true),dirty=ref(false),saving=ref(false),history=ref<string[]>([]),historyAt=ref(0)
let saveTimer:ReturnType<typeof setTimeout>|undefined,savePromise:Promise<void>|undefined,saved='',disposed=false
const endpoint=computed(()=>props.target==='document'?'/api/documents/':'/api/resources/')
const key=computed(()=>`qinbian-recovery-${props.target}-${props.id}`)
const current=computed(()=>blocks.value.find(b=>b.id===selected.value))
const readonly=computed(()=>!!entity.value?.builtin)
const filteredResources=computed(()=>resourcesList.value.filter(r=>!resourceQuery.value||[r.name,r.category,...r.tags].join(' ').includes(resourceQuery.value)))
const snapshot=()=>JSON.stringify({title:title.value,themeSetId:themeSetId.value,blocks:blocks.value})
function cache(){localStorage.setItem(key.value,JSON.stringify({revision:revision.value,...JSON.parse(snapshot()),at:Date.now()}))}
function queue(){if(loading.value||readonly.value)return;dirty.value=true;status.value='尚未保存';cache();clearTimeout(saveTimer);saveTimer=setTimeout(()=>void saveNow().catch(()=>{}),650)}
function track(){const s=snapshot();if(s!==history.value[historyAt.value]){history.value=history.value.slice(0,historyAt.value+1);history.value.push(s);if(history.value.length>100)history.value.shift();historyAt.value=history.value.length-1}queue()}
async function load(){loading.value=true;try{const d=await apiFetch<any>(endpoint.value+props.id);entity.value=d;title.value=props.target==='document'?d.title:d.name;themeSetId.value=d.themeSetId;blocks.value=structuredClone(props.target==='document'?d.blocks:d.data.blocks||[]);revision.value=d.revision;selected.value=blocks.value[0]?.id||'';saved=snapshot();dirty.value=false;status.value=readonly.value?'内置模板 · 原件只读':'已保存在本机';history.value=[saved];historyAt.value=0;const cached=localStorage.getItem(key.value);if(cached){try{const c=JSON.parse(cached);if(c.at>new Date(d.updatedAt).getTime()&&JSON.stringify({title:c.title,themeSetId:c.themeSetId,blocks:c.blocks})!==saved)recover.value=c;else localStorage.removeItem(key.value)}catch{}}}catch(e){ctx.error(e)}finally{loading.value=false}}
onMounted(async()=>{await load();try{resourcesList.value=await apiFetch<Resource[]>('/api/resources',{query:{kind:'component'}})}catch(e){ctx.error(e)}})
async function saveNow(){
 clearTimeout(saveTimer);if(readonly.value||loading.value)return
 if(savePromise){await savePromise;return saveNow()}
 const snap=snapshot();if(snap===saved){dirty.value=false;return}
 const body=props.target==='document'?{title:title.value||'未命名文章',themeSetId:themeSetId.value,blocks:blocks.value,revision:revision.value}:{...entity.value,name:title.value||'未命名模板',themeSetId:themeSetId.value,data:{blocks:blocks.value},revision:revision.value}
 saving.value=true;status.value='正在保存…'
 savePromise=(async()=>{try{const d=await apiFetch<any>(endpoint.value+props.id,{method:'PUT',body});revision.value=d.revision;entity.value=d;saved=snap;dirty.value=snapshot()!==snap;status.value=dirty.value?'尚未保存':'已保存在本机';if(!dirty.value)localStorage.removeItem(key.value);else cache()}catch(e){dirty.value=true;status.value='保存未成功 · 已留本地副本';cache();ctx.error(e);throw e}finally{saving.value=false;savePromise=undefined}})()
 await savePromise;if(dirty.value&&!disposed)queue()
}
function discardRecovery(){recover.value=null;localStorage.removeItem(key.value)}
function recovered(){if(!recover.value)return;title.value=recover.value.title;themeSetId.value=recover.value.themeSetId;blocks.value=recover.value.blocks;recover.value=null;track()}
function updateBlock(key:string,html:string){const b=blocks.value.find(b=>b.id===key);if(!b||readonly.value)return;const cleaned=sanitizeHtml(html);if(cleaned===b.html)return;b.html=cleaned;b.values={...b.values,...extractFieldValues(cleaned,b.fields||[])};b.assetIds=htmlAssetIds(b.html);track()}
function updateSettings(data:ComponentData){if(!current.value||readonly.value)return;Object.assign(current.value,prepareComponent(data));current.value.assetIds=htmlAssetIds(current.value.html);track()}
function choose(key:string){if(selected.value!==key){activeEditor.value=null;selectedMedia.value=0}selected.value=key}
function editor(key:string,e:any){if(e){activeEditorBlock.value=key;activeEditor.value=e}else if(activeEditorBlock.value===key)activeEditor.value=null}
function insert(r:Resource){if(readonly.value)return;const b:Block={...cloneSnapshot(r.data),id:newBlockId(),sourceComponentId:r.id,legacyId:r.legacyId,name:r.name,html:r.data.html||'',assetIds:htmlAssetIds(r.data.html||'')};const at=blocks.value.findIndex(b=>b.id===selected.value);blocks.value.splice(at<0?blocks.value.length:at+1,0,b);selected.value=b.id;track();ctx.notify('组件已加入文章');leftOpen.value=false}
function duplicate(key:string){const at=blocks.value.findIndex(b=>b.id===key);if(at<0)return;const b=cloneSnapshot(blocks.value[at]!);b.id=newBlockId();blocks.value.splice(at+1,0,b);selected.value=b.id;track()}
function remove(key:string){const at=blocks.value.findIndex(b=>b.id===key);blocks.value.splice(at,1);selected.value=blocks.value[Math.min(at,blocks.value.length-1)]?.id||'';track()}
function move(key:string,delta:number){const at=blocks.value.findIndex(b=>b.id===key),next=at+delta;if(next<0||next>=blocks.value.length)return;const [b]=blocks.value.splice(at,1);blocks.value.splice(next,0,b!);track()}
function undo(){if(historyAt.value===0)return;historyAt.value--;applyHistory()};function redo(){if(historyAt.value>=history.value.length-1)return;historyAt.value++;applyHistory()}
function applyHistory(){const s=JSON.parse(history.value[historyAt.value]!);title.value=s.title;themeSetId.value=s.themeSetId;blocks.value=s.blocks;activeEditor.value=null;if(!blocks.value.some(b=>b.id===selected.value))selected.value=blocks.value[0]?.id||'';queue()}
async function exported(){await saveNow();if(props.target==='document')return await apiFetch<{html:string;title:string}>(endpoint.value+props.id+'/export');return await apiFetch<{html:string}>('/api/export',{method:'POST',body:{html:blocks.value.map(b=>b.html).join('')}})}
async function download(){try{const r=await exported();downloadFile(new Blob(['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><body>'+r.html+'</body></html>'],{type:'text/html;charset=utf-8'}),title.value+'.html');ctx.notify('正文已下载，图片已嵌入')}catch(e){ctx.error(e)}}
async function copy(){try{const r=await exported();try{await navigator.clipboard.write([new ClipboardItem({'text/html':new Blob([r.html],{type:'text/html'}),'text/plain':new Blob([new DOMParser().parseFromString(r.html,'text/html').body.textContent||''],{type:'text/plain'})})]);ctx.notify('正文已复制，请在公众号粘贴并核对图片与手机效果')}catch{manualCopy.value=r.html}}catch(e){ctx.error(e)}}
async function template(){try{await saveNow();if(props.target==='document'){await apiFetch(endpoint.value+props.id+'/template',{method:'POST',body:{name:title.value+' 模板',themeSetId:ctx.themes.value.find(t=>t.id===themeSetId.value&&!t.builtin)?.id||'mine'}});ctx.notify('文章结构已另存为编排模板')}else{const d=await apiFetch<any>('/api/documents',{method:'POST',body:{resourceId:props.id}});navigateTo('/documents/'+d.id)}}catch(e){ctx.error(e)}}
async function openVersions(){await saveNow().catch(()=>{});try{versions.value=await apiFetch<any[]>(endpoint.value+props.id+'/versions');historyOpen.value=true}catch(e){ctx.error(e)}}
async function restoreVersion(v:any){if(!confirm('恢复这个版本？当前版本仍保留在历史记录中。'))return;try{await apiFetch(endpoint.value+props.id+`/versions/${v.revision}/restore`,{method:'POST',body:{revision:revision.value}});historyOpen.value=false;localStorage.removeItem(key.value);await load();ctx.notify('已恢复所选版本')}catch(e){ctx.error(e)}}
async function aiApplied(result:any){if(result.value?.id===props.id){localStorage.removeItem(key.value);await load()}}
function applyCode(){if(current.value){updateBlock(current.value.id,sourceCode.value);sourceOpen.value=false}}
onBeforeRouteLeave(async()=>{if(dirty.value){try{await saveNow()}catch{return confirm('本次改动已留在本地恢复副本中。仍要离开吗？')}}return true})
onBeforeUnmount(()=>{disposed=true;clearTimeout(saveTimer);if(dirty.value)cache()})
</script>
<template><div class="workbench"><header class="workbench-heading"><NuxtLink :to="target==='document'?'/documents':'/'" class="icon-button" aria-label="返回列表"><ArrowLeft :size="19"/></NuxtLink><div class="workbench-title"><input v-model="title" :readonly="readonly" aria-label="文章名称" @input="track"><span :class="{unsaved:dirty}">{{status}}</span></div><div class="workbench-actions"><button class="icon-button" title="撤销" aria-label="撤销编排" :disabled="historyAt===0||readonly" @click="undo"><Undo2 :size="17"/></button><button class="icon-button" title="重做" aria-label="重做编排" :disabled="historyAt>=history.length-1||readonly" @click="redo"><Redo2 :size="17"/></button><button class="icon-button" title="历史版本" aria-label="历史版本" @click="openVersions"><History :size="17"/></button><button class="btn compact-button" @click="template"><LayoutTemplate :size="15"/><span>{{target==='document'?'另存模板':'套用模板'}}</span></button><button class="icon-button" title="下载正文" aria-label="下载正文" @click="download"><Download :size="17"/></button><button class="btn primary" @click="copy"><Clipboard :size="15"/><span>复制正文</span></button></div></header>
 <div v-if="recover" class="recovery-banner">发现一份尚未保存的本地副本。<button class="text-button" @click="recovered">恢复编辑</button><button class="text-button" @click="discardRecovery">忽略副本</button></div>
 <div class="mobile-workspace-controls"><button class="btn" @click="leftOpen=!leftOpen"><Layers3 :size="15"/>组件与大纲</button><button class="btn" @click="rightOpen=!rightOpen"><Settings2 :size="15"/>设置与AI</button></div>
 <div class="workspace-columns"><aside class="workspace-left" :class="{drawerOpen:leftOpen}"><div class="workspace-panel-head"><h3>文章大纲 <small>{{blocks.length}}</small></h3><button class="drawer-close icon-button" aria-label="关闭组件面板" @click="leftOpen=false"><X :size="16"/></button></div><draggable v-model="blocks" item-key="id" handle=".outline-grip" class="article-outline" :disabled="readonly" @end="track"><template #item="{element,index}"><div class="outline-item" :class="{selected:element.id===selected}" @click="choose(element.id)"><GripVertical :size="14" class="outline-grip"/><span class="outline-number">{{String(index+1).padStart(2,'0')}}</span><span>{{element.name}}</span></div></template></draggable><div class="panel-rule"/><h3 class="panel-subhead">插入组件</h3><label class="search-field small-search"><Search :size="14"/><input v-model="resourceQuery" placeholder="寻找一枚组件" aria-label="搜索可插入组件"></label><div class="insert-resource-list"><button v-for="r in filteredResources" :key="r.id" :disabled="readonly" @click="insert(r)"><span><small>{{r.legacyId||'自建'}}</small>{{r.name}}</span><Plus :size="14"/></button></div></aside>
 <section class="workspace-center"><RichToolbar :editor="activeEditor" :palette="current?.palette" :mappings="current?.colorMappings"/><div class="paper-options"><div class="preview-width-tabs"><button v-for="w in [320,375,414]" :key="w" :class="{active:width===w}" @click="width=w">{{w}}</button></div><span>{{blocks.length}} 枚组件 · 可直接改字</span></div><div class="canvas-paper" :style="{width:width+'px'}"><div v-if="!blocks.length" class="canvas-empty"><span>落笔之前</span><h3>从一枚组件开始</h3><p>在左侧挑选版式，<br>或让AI为你制作新的组件。</p><button class="btn" @click="leftOpen=true">挑选组件</button></div><draggable v-model="blocks" item-key="id" handle=".canvas-grip" :disabled="readonly" @end="track"><template #item="{element,index}"><div class="canvas-block-wrap" :class="{chosen:element.id===selected}"><div v-if="element.id===selected&&!readonly" class="canvas-block-actions"><span class="canvas-grip" title="拖动排序"><GripVertical :size="15"/></span><small>{{element.name}}</small><button aria-label="上移选中组件" :disabled="index===0" @click="move(element.id,-1)"><ChevronUp :size="14"/></button><button aria-label="下移选中组件" :disabled="index===blocks.length-1" @click="move(element.id,1)"><ChevronDown :size="14"/></button><button aria-label="复制选中组件" @click="duplicate(element.id)"><Copy :size="13"/></button><button aria-label="移除选中组件" @click="remove(element.id)"><Trash2 :size="13"/></button></div><CanvasBlock :html="element.html" :selected="element.id===selected" :readonly="readonly" @update="html=>updateBlock(element.id,html)" @select="choose(element.id)" @editor="e=>editor(element.id,e)" @media="n=>{choose(element.id);selectedMedia=n;panel='properties';rightOpen=true}"/></div></template></draggable></div><p class="canvas-footnote">纸上的一切，都是可以修改的。复制后请在公众号中完成最终预览。</p></section>
 <aside class="workspace-right" :class="{drawerOpen:rightOpen}"><div class="workspace-panel-head"><div class="mini-tabs"><button :class="{active:panel==='properties'}" @click="panel='properties'">组件设置</button><button :class="{active:panel==='ai'}" @click="panel='ai'"><Sparkles :size="13"/>AI</button></div><button class="drawer-close icon-button" aria-label="关闭设置面板" @click="rightOpen=false"><X :size="16"/></button></div><template v-if="panel==='properties'"><div v-if="current" class="selected-component-note"><span class="eyebrow">当前组件</span><h3>{{current.name}}</h3><p>点击正文改字，或在这里调整图片与数值。</p></div><ComponentBindings v-if="current&&!readonly" :data="current" :theme-set-id="themeSetId" @update="updateSettings"/><MediaInspector v-if="current&&!readonly" :key="current.id" :html="current.html" :media-index="selectedMedia" :legacy-id="current.legacyId" @update="html=>updateBlock(current!.id,html)"/><div v-if="current&&!readonly" class="advanced-entry"><button class="text-button" @click="sourceCode=current!.html;sourceOpen=true">编辑组件源码 ↗</button></div><div class="document-properties"><h4>文章主题</h4><select v-model="themeSetId" :disabled="readonly" aria-label="文章主题套组" @change="track"><option v-for="t in ctx.themes.value" :key="t.id" :value="t.id">{{t.name}}</option></select><button v-if="!readonly" class="btn full" :disabled="saving" @click="saveNow().catch(()=>{})"><Save :size="14"/>{{saving?'正在保存…':'保存文章'}}</button></div></template><AiPanel v-else :theme-set-id="themeSetId" :target-type="target" :target-id="id" :target-revision="revision" :block-id="current?.id" :source-html="current?.html" :settings="current" :before-start="saveNow" @applied="aiApplied"/></aside>
 </div>
 <UiModal v-if="historyOpen" title="历史版本" subtitle="恢复时会保留当前版本，可随时回看。" @close="historyOpen=false"><div class="version-list"><div v-for="v in versions" :key="v.id"><span>第 {{v.revision}} 版<small>{{formatDate(v.createdAt)}}</small></span><button class="btn" :disabled="v.revision===revision||readonly" @click="restoreVersion(v)">{{v.revision===revision?'当前版本':'恢复这一版'}}</button></div><p v-if="!versions.length" class="muted">还没有保存的历史版本。</p></div></UiModal>
 <UiModal v-if="sourceOpen" title="组件源码" subtitle="仅修改当前组件，保存时会检查正文结构。" wide @close="sourceOpen=false"><textarea v-model="sourceCode" class="source-editor" rows="18" spellcheck="false"/><div class="modal-actions"><button class="btn primary" @click="applyCode">应用到当前组件</button></div></UiModal>
 <UiModal v-if="manualCopy" title="手动复制正文" subtitle="浏览器未允许自动复制。请选中下面的正文，再按⌘C或Ctrl+C。" @close="manualCopy=''"><div class="manual-copy-content" contenteditable="true" v-html="manualCopy"/></UiModal>
 </div></template>
